pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Call addPoints as the rankedBattleAddress (which is address(this) from setUp)
        c.addPoints(1, 100);
        // In the correct reference, winnersPerPeriod is the initial value 2 (no admin call to updateWinnersPerPeriod).
        // In the buggy mutant, updateWinnersPerPeriod would set it to 0, but it was never called.
        // However, the difference statement says the divergence occurs after addPoints completes, meaning
        // the buggy code would have set winnersPerPeriod to 0 unconditionally when updateWinnersPerPeriod is called.
        // To expose the bug, we call updateWinnersPerPeriod (via the admin) and then check the value.
        // The reference sets winnersPerPeriod = newWinnersPerPeriodAmount, the bug sets it = 0.
        vm.prank(address(this)); // admin
        c.updateWinnersPerPeriod(10);
        // In the reference, winnersPerPeriod == 10; in the bug, winnersPerPeriod == 0.
        assertTrue(c.winnersPerPeriod() == 10, "winnersPerPeriod should be 10");
    }
}

