import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // set caller to the ranked battle address (this contract)
        vm.prank(address(this));
        c.addPoints(1, 200);
        // reference: totalPoints == 200, bug: totalPoints == 0
        assertTrue(c.totalPoints() == 200);
    }
}

